    "Versión trabajada por el investigador.": "The version worked on by the researcher.",
    "Versión {n} del acuerdo": "Agreement version {n}",
    "Vistas guardadas": "Saved views",
    "Vídeo": "Video",
    "Ya existe «{name}»: se reutilizará en vez de crear un duplicado.": "“{name}” already exists: it will be reused instead of creating a duplicate.",
    "sin huella": "no checksum",
    "{changed} tramos corregidos · {rejected} rechazados por cambiar palabras": "{changed} segments corrected · {rejected} rejected for changing words",
    "{codes} códigos · {annotations} fragmentos codificados": "{codes} codes · {annotations} coded fragments",
    "{indexed} de {indexable} entrevistas indexadas · {segments} tramos": "{indexed} of {indexable} interviews indexed · {segments} segments",
